package com.loopers.infrastructure.payment
import com.fasterxml.jackson.databind.JsonNode;import com.loopers.domain.payment.PaymentGateway;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;import org.springframework.web.util.UriComponentsBuilder
// Hides: simulator HTTP paths, nested response parsing, headers, and URI encoding.
@Component class PgSimulatorPaymentGateway:PaymentGateway{private val client=RestClient.create("http://localhost:8082");private fun result(n:JsonNode):PaymentGateway.Result{val d=n.path("data");return PaymentGateway.Result(d.path("transactionKey").asText(),d.path("orderId").asText(),d.path("status").asText())};override fun create(userId:String,request:PaymentGateway.Request):PaymentGateway.Result{val x=result(client.post().uri("/api/v1/payments").header("X-USER-ID",userId).body(request).retrieve().body(JsonNode::class.java)!!);return PaymentGateway.Result(x.transactionKey,request.orderId,x.status)};override fun findByOrderId(userId:String,providerOrderId:String):List<PaymentGateway.Result>{val uri=UriComponentsBuilder.fromPath("/api/v1/payments").queryParam("orderId",providerOrderId).build().encode().toUriString();val d=client.get().uri(uri).header("X-USER-ID",userId).retrieve().body(JsonNode::class.java)!!.path("data");val rows=if(d.has("transactions"))d.path("transactions") else d;return if(rows.isArray)rows.map{PaymentGateway.Result(it.path("transactionKey").asText(),providerOrderId,it.path("status").asText())}else emptyList()};override fun findByTransactionKey(userId:String,key:String)=result(client.get().uri("/api/v1/payments/{key}",key).header("X-USER-ID",userId).retrieve().body(JsonNode::class.java)!!)}
